def lazy_call(self, callback):
    if hasattr(torch.xpu, "_lazy_call"):
        return torch.xpu._lazy_call(callback)
    else:
        return torch.xpu.lazy_init._lazy_call(callback)

def communication_backend_name(self):
    return self._communication_backend_name

def is_triton_supported(self):
    return False

# Graph operations
def is_graph_capture_supported(self) -> bool:
    return torch.xpu.is_available() and hasattr(torch.xpu, 'is_current_stream_capturing')

def is_current_stream_capturing(self) -> bool:
    if not hasattr(torch.xpu, 'is_current_stream_capturing'):
        return False
    return torch.xpu.is_current_stream_capturing()

def create_graph(self):
    if not hasattr(torch.xpu, 'XPUGraph'):
        return None
    return torch.xpu.XPUGraph()

def capture_to_graph(self, graph, pool=None, stream=None):
    if graph is None:
        from deepspeed.runtime.utils import noop_context
        return noop_context()
    return torch.xpu.graph(graph, pool, stream)

def replay_graph(self, graph):
    if graph is not None:
        graph.replay()
    return

# Data types
def is_bf16_supported(self):
    return True

def is_fp16_supported(self):
    return True

